// Everything returned here is marked first_party: true. Downstream copy generation may state
// a first-party fact plainly; a web finding must be attributed.
const raw = $json;
const want = $('Envelope In').first().json.payload.extract || null;
const facts = [];

if (Array.isArray(raw.reviews)) {
  const phrases = {};
  for (const r of raw.reviews) for (const s of String(r.body || '').split(/[.!?]/)) { const t = s.trim().toLowerCase(); if (t.length > 20 && t.length < 120) phrases[t] = (phrases[t] || 0) + 1; }
  const recurring = Object.entries(phrases).sort((a, b) => b[1] - a[1]).slice(0, 10);
  facts.push({ kind: 'recurring_customer_language', value: recurring.map(([t, n]) => ({ phrase: t, count: n })), first_party: true });
  facts.push({ kind: 'review_score', value: (raw.reviews.reduce((a, r) => a + (r.rating || 0), 0) / raw.reviews.length).toFixed(2), sample: raw.reviews.length, first_party: true });
}
if (raw.attributes) facts.push({ kind: 'attributes', value: raw.attributes, first_party: true });
if (raw.specs) facts.push({ kind: 'specifications', value: raw.specs, first_party: true });
if (raw.account) facts.push({ kind: 'account_context', value: raw.account, first_party: true });

return [{ json: { facts, requested: want, source: $('Envelope In').first().json.payload.source || 'catalog', citable_without_attribution: true } }];
